/**
 * Shared bootstrap for every endpoint in api/.
 *
 * Responsibilities:
 *   - load the database credentials (never from inside the web root),
 *   - open one lazily created PDO connection to the local MySQL server,
 *   - provide tiny helpers for JSON output, error output and parameter parsing.
 *
 * Nothing here may ever echo a credential: errors are always reported as a
 * short JSON message.
 */

/** Where to look for the configuration, first match wins. */
const PI_SENSOR_CONFIG_CANDIDATES = [
    '/etc/pi_sensor/web.ini',
    __DIR__ . '/../../etc/web_db.ini',
];

/** Fields (SQL columns) the API is allowed to read. */
const PI_SENSOR_FIELDS = [
    'temp_inside',
    'hum_inside',
    'temp_outside',
    'hum_outside',
];

/** Allowed values for the "bucket" parameter. */
const PI_SENSOR_BUCKETS = ['5m', '1h', '1d'];

/** Longest window we allow for the stats endpoint, in hours (one year). */
const PI_SENSOR_MAX_HOURS = 8760;

// ---------------------------------------------------------------------------
// Output helpers
// ---------------------------------------------------------------------------

/**
 * Emit a JSON response and terminate. Values are encoded with unescaped
 * slashes/unicode so the payload stays small, and numeric strings are kept as
 * numbers by the callers, not by this function.
 */
function json_out(mixed $data, int $status = 200, int $maxAge = 0): never
{
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: ' . ($maxAge > 0 ? "public, max-age={$maxAge}" : 'no-store'));

    echo json_encode(
        $data,
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
    );
    exit;
}

/** Emit a JSON error body and terminate. */
function json_error(string $message, int $status = 400): never
{
    json_out(['error' => $message], $status);
}

