/**
 * Read the [database] section.
 *
 * Precedence: environment variables first (handy for containers), then the ini
 * file. The ini file must live outside the document root.
 *
 * @return array{host:string,port:int,database:string,username:string,password:string}
 */
function db_config(): array
{
    $config = [
        'host' => 'localhost',
        'port' => 3306,
        'database' => 'bleihuetten',
        'username' => '',
        'password' => '',
    ];

    $path = null;
    foreach (PI_SENSOR_CONFIG_CANDIDATES as $candidate) {
        if (is_readable($candidate)) {
            $path = $candidate;
            break;
        }
    }

    if ($path !== null) {
        // INI_SCANNER_RAW keeps values verbatim: a numeric password must not
        // become an int and "true"/"null" must not become bool/null.
        $ini = parse_ini_file($path, true, INI_SCANNER_RAW);
        if ($ini === false) {
            json_error('Konfiguration kann nicht gelesen werden', 500);
        }

        $section = $ini['database'] ?? [];
        if (!is_array($section)) {
            json_error('Konfiguration hat keine [database] Sektion', 500);
        }

        foreach ($config as $key => $default) {
            if (isset($section[$key]) && $section[$key] !== '') {
                $config[$key] = $key === 'port' ? (int) $section[$key] : (string) $section[$key];
            }
        }
    }

    foreach (['host', 'port', 'database', 'username', 'password'] as $key) {
        $env = getenv('PI_SENSOR_DB_' . strtoupper($key));
        if ($env !== false && $env !== '') {
            $config[$key] = $key === 'port' ? (int) $env : $env;
        }
    }

    if ($config['username'] === '') {
        json_error('Datenbankkonfiguration fehlt', 500);
    }

    return $config;
}

// ---------------------------------------------------------------------------
// Database
// ---------------------------------------------------------------------------

/** Lazily created, shared PDO connection. */
function db(): PDO
{
    static $pdo = null;

    if ($pdo instanceof PDO) {
        return $pdo;
    }

    $config = db_config();

    $dsn = sprintf(
        'mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',
        $config['host'],
        $config['port'],
        $config['database']
    );

    try {
        $pdo = new PDO($dsn, $config['username'], $config['password'], [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES => false,
            PDO::ATTR_STRINGIFY_FETCHES => false,
        ]);
    } catch (PDOException $e) {
        // The driver message may contain the host/user but never the password.
        error_log('pi_sensor: database connection failed: ' . $e->getMessage());
        json_error('Datenbank nicht erreichbar', 503);
    }

    // `measured_at` is Pi-local wall-clock time. UNIX_TIMESTAMP() must therefore
    // interpret it in the server's local time zone, which is the default
    // session time zone - do not override it.
    return $pdo;
}

/**
 * Start of a "last N hours" window as a DATETIME string.
 *
 * The reference "now" is taken from the database, not from PHP: PHP runs with
 * date.timezone=UTC here while MariaDB runs in local time (CET), so a window
 * computed in PHP would be shifted by the UTC offset. `measured_at` holds naive
 * Pi-local wall-clock time and must be compared against the database's clock.
 */
function db_since(int $hours): string
{
    $statement = db()->prepare('SELECT DATE_SUB(NOW(), INTERVAL ? HOUR) AS window_start');
    $statement->bindValue(1, $hours, PDO::PARAM_INT);
    $statement->execute();

    $value = $statement->fetchColumn();
    if (!is_string($value) && !is_numeric($value)) {
        json_error('Zeitfenster konnte nicht bestimmt werden', 500);
    }

    return (string) $value;
}

