/** Read an integer query parameter, clamped to [$min, $max]. */
function query_int(string $name, int $default, int $min, int $max): int
{
    $raw = $_GET[$name] ?? null;
    if ($raw === null || $raw === '') {
        return $default;
    }
    if (!is_string($raw) || !preg_match('/^-?\d+$/', $raw)) {
        json_error("Parameter '{$name}' muss eine ganze Zahl sein");
    }
    $value = (int) $raw;
    if ($value < $min || $value > $max) {
        json_error("Parameter '{$name}' muss zwischen {$min} und {$max} liegen");
    }
    return $value;
}

/** Read a query parameter that must be one of $allowed. */
function query_enum(string $name, array $allowed, string $default): string
{
    $raw = $_GET[$name] ?? null;
    if ($raw === null || $raw === '') {
        return $default;
    }
    if (!is_string($raw) || !in_array($raw, $allowed, true)) {
        json_error("Parameter '{$name}' muss einer von: " . implode(', ', $allowed) . ' sein');
    }
    return $raw;
}

/**
 * Read the "fields" parameter as a list of whitelisted column names.
 *
 * @return list<string>
 */
function query_fields(string $default): array
{
    $raw = $_GET['fields'] ?? null;
    if ($raw === null || $raw === '') {
        $raw = $default;
    }
    if (!is_string($raw)) {
        json_error("Parameter 'fields' muss Text sein");
    }

    $fields = [];
    foreach (explode(',', $raw) as $candidate) {
        $candidate = trim($candidate);
        if ($candidate === '') {
            continue;
        }
        if (!in_array($candidate, PI_SENSOR_FIELDS, true)) {
            json_error("Unbekanntes Feld '{$candidate}'");
        }
        if (!in_array($candidate, $fields, true)) {
            $fields[] = $candidate;
        }
    }

    if ($fields === []) {
        json_error("Parameter 'fields' darf nicht leer sein");
    }

    return $fields;
}

/** Parse a "YYYY-MM-DD" or "YYYY-MM-DD HH:MM:SS" value into a DATETIME string. */
function parse_datetime_param(string $name): ?string
{
    $raw = $_GET[$name] ?? null;
    if ($raw === null || $raw === '') {
        return null;
    }
    if (!is_string($raw)) {
        json_error("Parameter '{$name}' muss Text sein");
    }

    foreach (['Y-m-d H:i:s', 'Y-m-d'] as $format) {
        $date = DateTimeImmutable::createFromFormat($format, $raw);
        if ($date instanceof DateTimeImmutable) {
            $errors = DateTimeImmutable::getLastErrors();
            if ($errors === false || ($errors['warning_count'] === 0 && $errors['error_count'] === 0)) {
                return $date->format('Y-m-d H:i:s');
            }
        }
    }

    json_error("Parameter '{$name}' muss ein Datum (YYYY-MM-DD) oder Datum/Uhrzeit sein");
}

