/** DECIMAL columns arrive as strings from PDO; normalise to float|null. */
function to_float(mixed $value): ?float
{
    return $value === null ? null : (float) $value;
}

/** Bind one field's average expression as a rounded float|null. */
function round_or_null(mixed $value, int $decimals = 2): ?float
{
    return $value === null ? null : round((float) $value, $decimals);
}
